};

data.openseadragon-callback#OpenSeadragon Cal:
The Image component uses OpenSeadragon to render the image. The openSeadragonCallback prop provides a callback function that returns the OpenSeadragon Viewer instance. This can be used to programmatically control the viewer from the consuming application.
import Image from "@samvera/clover-iiif/image";
const MyCustomImage = () => {
  export const handleOpenSeadragonCallback = (viewer) => {
    console.log("OpenSeadragon instance is ready");
    console.log(viewer);
  };
  return (
    <Image
      src="https://ids.lib.harvard.edu/ids/iiif/18772291/full/full/0/default.jpg"
      openSeadragonCallback={handleOpenSeadragonCallback}
    />
  );
};

data.openseadragon-configuration#OpenSeadrago:
The openSeadragonConfig prop provides a way to configure the OpenSeadragon Viewer instance. This prop accepts an object of OpenSeadragon.Options.
import Image from "@samvera/clover-iiif/image";
const MyCustomImage = () => {
  const openSeadragonConfig = {
    showNavigator: false,
    showRotationControl: true,
    // ... other OpenSeadragon options
  };
  return (
    <Image
      src="https://ids.lib.harvard.edu/ids/iiif/18772291/full/full/0/default.jpg"
      openSeadragonConfig={openSeadragonConfig}
    />
  );
};

data.label-and-aria#Label and ARIA:
The label prop is used to provide an accessible name for the OpenSeadragon. This is used as the aria-label attribute on the viewport element wrapping the OpenSeadragon canvas.The label can be a string or a valid IIIF Presentation API 3.0 label.
import Image from "@samvera/clover-iiif/image";
const MyCustomImage = () => {
  return (
    <Image
      src="https://ids.lib.harvard.edu/ids/iiif/18772291/full/full/0/default.jpg"
      label="Self-Portrait at Eleven Years Old"
    />
  );
};
import Image from "@samvera/clover-iiif/image";
const MyCustomImage = () => {
  return (
    <Image
      src="https://ids.lib.harvard.edu/ids/iiif/18772291/full/full/0/default.jpg"
      label={{ en: ["Self-Portrait at Eleven Years Old"] }}
    />
  );
};

data.multiple-images#Multiple Images:
Both the src and body prop can be an array of image URLs or IIIF Image service IDs. This allows you to render multiple images in a single OpenSeadragon instance. If body is provided, the resources should be an array of content resources.
import Image from "@samvera/clover-iiif/image";
const MyCustomImage = () => {
  return (
    <Image
      src={[
        "https://iiif.dc.library.northwestern.edu/iiif/3/34906273-e661-4cf1-ae20-849c4d21d01c/full/1200,/0/default.jpg",
        "https://iiif.dc.library.northwestern.edu/iiif/3/cf9f7fc4-c242-4ca9-a77f-25daf355af92/full/1200,/0/default.jpg",
      ]}
      label="Michel Kovatchevitch correspondence, postcard"
    />
  );
};

data.annotations#Annotations:
The annotations prop is used to provide a list of web annotations to be rendered on the image. The annotations prop accepts an array of objects, each containing an annotation and a targetIndex. The annotation object should contain the IIIF annotation data, and the targetIndex should be the index of the target canvas in the src array, or 0 if the src is a single image.
import Image from "@samvera/clover-iiif/image";
const MyAnnotatedImage = () => {
  return (
    <Image
      src={[
        "https://iiif.dc.library.northwestern.edu/iiif/3/f7409acd-e3f9-496a-b733-81f46d4ffa4f/full/max/0/default.jpg",
      ]}
      label="Patten Gymnasium, Northwestern University, Evanston, Ill."
      annotations={[
        {
          annotation: {
            id: "https://iiif.dc.library.northwestern.edu/iiif/3/f7409acd-e3f9-496a-b733-81f46d4ffa4f/annotation/0",
            type: "Annotation",
            motivation: ["tagging"],
            body: [
              {
                id: "https://iiif.dc.library.northwestern.edu/iiif/3/f7409acd-e3f9-496a-b733-81f46d4ffa4f/annotation/0/body/0",
                type: "TextualBody",
                value: "1935 Ford Coupe",
                language: "en",
              },
            ],
            target: {
              type: "SpecificResource",
              source: {
                id: "https://iiif.dc.library.northwestern.edu/iiif/3/f7409acd-e3f9-496a-b733-81f46d4ffa4f/full/max/0/default.jpg",
                type: "Canvas",
              },
              selector: {
                type: "FragmentSelector",
                value: "xywh=1000,1850,1200,600",
              },
            },
          },
          targetIndex: 0,
        },
        {
          annotation: {
            id: "https://iiif.dc.library.northwestern.edu/iiif/3/f7409acd-e3f9-496a-b733-81f46d4ffa4f/annotation/1",
            type: "Annotation",
            motivation: ["tagging"],
            body: [
              {
                id: "https://iiif.dc.library.northwestern.edu/iiif/3/f7409acd-e3f9-496a-b733-81f46d4ffa4f/annotation/1/body/0",
                type: "TextualBody",
                value: "1934 Packard Sedan",
                language: "en",
              },
            ],
            target: {
              type: "SpecificResource",
              source: {
                id: "https://iiif.dc.library.northwestern.edu/iiif/3/f7409acd-e3f9-496a-b733-81f46d4ffa4f/full/max/0/default.jpg",
                type: "Canvas",
              },
              selector: {
                type: "FragmentSelector",
                value: "xywh=2300,1750,1550,800",
              },
            },
          },
          targetIndex: 0,
        },
      ]}
    />
  );
};
In this example, two annotations are provided targeting the src image, one for a 1935 Ford Coupe at coordinates xywh=1000,1850,1200,600 and another for a 1934 Packard Sedan at coordinates xywh=2300,1750,1550,800.

data.instance-id#Instance ID:
The instanceId prop is used to provide an identifier defined from the consuming application for the OpenSeadragon instance. This is used as the id attribute on the viewport element wrapping the OpenSeadragon canvas. instanceId is optional and by default the Image component will generate a unique identifier.
import Image from "@samvera/clover-iiif/image";
const MyCustomImage = () => {
  const instanceId = "my-defined-instance-id";
  const handleOpenSeadragonCallback = (viewer) => {
    console.log(viewer?.id);
    // openseadragon-my-defined-instance-id
  };
  return (
    <Image
      src="https://ids.lib.harvard.edu/ids/iiif/18772291/full/full/0/default.jpg"
      instanceId={instanceId}
      openSeadragonCallback={handleOpenSeadragonCallback}
    />
  );
};

data.nextjs#Next.js:
Implementation with Next.js requires a dynamic import because MapLibre GL assumes a browser document object.
import dynamic from "next/dynamic";
const Map = dynamic(
  () => import("@samvera/clover-iiif").then((Clover) => Clover.Map),
  { ssr: false },
);

data.navplace#navPlace:
Render geographic features from a IIIF navPlace value. The navPlace prop accepts a GeoJSON FeatureCollection, Feature, or bare geometry object. Feature properties.label may be a plain string or a IIIF InternationalString, and will be shown as a tooltip and popup.You can also pass a IIIF resource through iiifContent. Clover will extract navPlace values from Collections, Manifests, Canvases, and Annotations, and the popup will include the resource context that supplied the feature, including its label, summary, and thumbnail when present.
<Map
  iiifContent="https://iiif.io/api/cookbook/recipe/0240-navPlace-on-canvases/manifest.json"
  navPlaceLevel="Canvas"
  fitToData
/>
The example below uses features from IIIF Cookbook recipe 0240: navPlace on Canvases, where navPlace is declared directly on each Canvas. To consume it, fetch the manifest and read canvas.navPlace from each item:
// Fetch the manifest and collect navPlace features from all canvases
const manifest = await fetch(
  "https://iiif.io/api/cookbook/recipe/0240-navPlace-on-canvases/manifest.json"
).then((r) => r.json());
const navPlace = {
  type: "FeatureCollection",
  features: manifest.items.flatMap(
    (canvas) => canvas.navPlace?.features ?? []
  ),
};
// navPlace now contains two features:
// - Current Location of the Laocoön Bronze  [-118.47, 34.07]  (Getty, Los Angeles)
// - Current Location of Painting            [-77.02,  38.89]  (National Gallery, DC)
<div style={{ height: "400px" }}>
  <Map navPlace={navPlace} fitToData />
</div>

data.polygon#Polygon:
A Polygon geometry draws a filled region. This example uses a bounding box from GeoNames to outline the extent of Lake Michigan.
const navPlace = {
  type: "Feature",
  properties: { label: { en: ["Lake Michigan"] } },
  geometry: {
    type: "Polygon",
    coordinates: [
      [
        [-87.91178, 41.61793], // SW
        [-84.72398, 41.61793], // SE
        [-84.72398, 46.10230], // NE
        [-87.91178, 46.10230], // NW
        [-87.91178, 41.61793], // close ring
      ],
    ],
  },
};
<div style={{ height: "400px" }}>
  <Map navPlace={navPlace} fitToData />
</div>

data.geometrycollection#GeometryCollection:
A GeometryCollection bundles multiple geometry types into a single navPlace feature. This example maps the western Lake Michigan shoreline as a composite: a bounding Polygon for the lake, a LineString tracing the shore from Gary to Green Bay, and a MultiPoint marking five lakeshore cities, all sharing one label.
const navPlace = {
  type: "Feature",
  properties: { label: { en: ["Lake Michigan Shoreline"] } },
  geometry: {
    type: "GeometryCollection",
    geometries: [
      {
        type: "Polygon",
        coordinates: [[
          [-87.91178, 41.61793],
          [-84.72398, 41.61793],
          [-84.72398, 46.10230],
          [-87.91178, 46.10230],
          [-87.91178, 41.61793],
        ]],
      },
      {
        type: "LineString",
        coordinates: [
          [-87.34643, 41.59337], // Gary, IN
          [-87.65005, 41.85003], // Chicago, IL
          [-87.90647, 43.03890], // Milwaukee, WI
          [-88.01983, 44.51916], // Green Bay, WI
        ],
      },
      {
        type: "MultiPoint",
        coordinates: [
          [-87.34643, 41.59337], // Gary, IN
          [-87.65005, 41.85003], // Chicago, IL
          [-87.90647, 43.03890], // Milwaukee, WI
          [-88.01983, 44.51916], // Green Bay, WI
          [-85.62063, 44.76306], // Traverse City, MI
        ],
      },
    ],
  },
};
<div style={{ height: "400px" }}>
  <Map navPlace={navPlace} fitToData />
</div>

data.georeference-extension#Georeference Exte:
Render Ground Control Points (GCPs) from a IIIF Georeference Extension annotation. Pass a parsed annotation object to georefAnnotation and the component will extract the GCPs and display them as numbered markers on the map. GCPs are included in fitToData bounds.The example below uses a real annotation from Northwestern University Libraries' Map of the Township of Evanston, Cook County, Illinois. The annotation's target.source is a Canvas.
// Annotation as returned by dc-api; target.source.type is "Canvas"
const georefAnnotation = {
  "@context": [
    "http://iiif.io/api/extension/georef/1/context.json",
    "http://iiif.io/api/presentation/3/context.json",
  ],
  id: "urn:meadow:georeference:2fb1e81a-...",
  type: "Annotation",
  motivation: "georeferencing",
  target: {
    type: "SpecificResource",
    source: {
      id: "https://api.dc.library.northwestern.edu/api/v2/file-sets/2fb1e81a-9e24-420c-b224-0bfd6a279baf?as=iiif",
      type: "Canvas",
      width: 7337,
      height: 9833,
    },
    selector: { type: "SvgSelector", value: "<svg ...>" },
  },
  body: {
    type: "FeatureCollection",
    features: [
      {
        type: "Feature",
        properties: { confidence: "medium", resourceCoords: [577.7, 1074.97] },
        geometry: { type: "Point", coordinates: [-87.71064, 42.06793] },
      },
      // ... 2 more GCPs
    ],
  },
};
<div style={{ height: "400px" }}>
  <Map georefAnnotation={georefAnnotation} fitToData />
</div>

data.warped-image-overlay#Warped Image Overla:
When showImageOverlay is enabled and a georefAnnotation with at least 3 GCPs is provided, the component renders a warped IIIF image overlay using @allmaps/maplibre.Important: @allmaps/maplibre requires the annotation's target.source to reference an IIIF Image API endpoint (type: "ImageService2" or "ImageService3"), not a Canvas. Annotations saved by authoring tools typically use a Canvas source. Use the adaptGeoreferenceAnnotationForOverlay helper to swap the source before passing it to <Map>.The example below uses the same Evanston map annotation adapted with the FileSet's IIIF Image API v3 endpoint as the ImageService3 source.
import Map, { adaptGeoreferenceAnnotationForOverlay } from "@samvera/clover-iiif/map";
// Annotation target.source.type is "Canvas"
const storedAnnotation = { /* ... */ };
// IIIF Image API v3 base URL for the FileSet
const imageServiceId =
  "https://iiif.dc.library.northwestern.edu/iiif/3/2fb1e81a-9e24-420c-b224-0bfd6a279baf";
// Adapt the annotation so @allmaps/maplibre can use it
const overlayAnnotation = adaptGeoreferenceAnnotationForOverlay(
  storedAnnotation,
  imageServiceId,
);
<div style={{ height: "500px" }}>
  <Map
    georefAnnotation={overlayAnnotation}
    showImageOverlay
    imageOverlayOpacity={0.65}
    fitToData
  />
</div>
@allmaps/maplibre is an optional dependency. It is only loaded when showImageOverlay is true, so consumers who don't use this feature pay no bundle cost.

data.coordinate-picking#Coordinate Picking:
Use onMapClick and useCrosshairCursor to turn the map into a coordinate picker. The callback receives [longitude, latitude] rounded to five decimal places.
const [coordinates, setCoordinates] = React.useState(null);
<div>
  <div style={{ height: "400px" }}>
    <Map
      center={{ latitude: 42.045, longitude: -87.688, zoom: 11 }}
      markers={
        coordinates
          ? [
              {
                latitude: coordinates.lat,
                longitude: coordinates.lng,
                label: "Selected coordinate",
              },
            ]
          : []
      }
      onMapClick={([lng, lat]) => setCoordinates({ lng, lat })}
      useCrosshairCursor
    />
  </div>
  <output>
    {coordinates
      ? `longitude: ${coordinates.lng}, latitude: ${coordinates.lat}`
      : "Click the map to pick coordinates."}
  </output>
</div>

data.georeferenceannotation-type#Georeference:
A IIIF Georeference Extension annotation. The body is a GeoJSON FeatureCollection whose features carry properties.resourceCoords (image pixel [x, y]) paired with a Point geometry (geographic [longitude, latitude]).
interface GeoreferenceAnnotation {
  "@context"?: string | string[];
  id?: string;
  type: "Annotation";
  motivation: "georeferencing";
  target: {
    type: "SpecificResource";
    source: {
      id: string;
      type: string; // "Canvas" | "ImageService2" | "ImageService3"
      width?: number;
      height?: number;
    };
    selector?: { type: "SvgSelector"; value: string };
  };
  body: GeoJSON.FeatureCollection;
}

data.mapmarker-type#MapMarker type:
interface MapMarker {
  latitude: number;
  longitude: number;
  label?: string;
}

data.mapcenter-type#MapCenter type:
interface MapCenter {
  latitude: number;
  longitude: number;
  zoom: number;
}

data.maptilelayer-type#MapTileLayer type:
interface MapTileLayer {
  url: string; // e.g. "https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
  attribution: string;
}

data.parsegeoreferenceannotation#parseGeorefe:
Extracts Ground Control Points from a GeoreferenceAnnotation. Features with missing or non-numeric coordinates are silently skipped.
import { helpers } from "@samvera/clover-iiif";
const gcps = helpers.parseGeoreferenceAnnotation(annotation);
// → [{ id, resourceCoords: [x, y], geoCoords: [lng, lat] }, ...]

data.adaptgeoreferenceannotationforoverlay#ad:
Swaps a Canvas source for an ImageService source so the annotation can be used with @allmaps/maplibre. Does not mutate the input.
import { adaptGeoreferenceAnnotationForOverlay } from "@samvera/clover-iiif";
const overlayAnnotation = adaptGeoreferenceAnnotationForOverlay(
  storedAnnotation, // GeoreferenceAnnotation with Canvas source
  imageServiceId, // IIIF Image API base URL
  "ImageService3", // default; pass "ImageService2" for Image API 2 services
);

data.normalizenavplace#normalizeNavPlace:
Normalises any GeoJSON value (FeatureCollection, Feature, or bare geometry) to a FeatureCollection. Returns null for unrecognised input.
import { helpers } from "@samvera/clover-iiif";
const featureCollection = helpers.normalizeNavPlace(canvas.navPlace);

data.extractnavplacefeatures#extractNavPlaceF:
Extracts navPlace features from IIIF resources and annotates each feature with the Collection, Manifest, Canvas, or Annotation that supplied it.
import { extractNavPlaceFeatures } from "@samvera/clover-iiif";
const features = extractNavPlaceFeatures(manifest, { levels: ["Canvas"] });

data.getnavplacelabel#getNavPlaceLabel:
Resolves a navPlace Feature label property to a display string, handling both plain strings and IIIF InternationalString.
import { helpers } from "@samvera/clover-iiif";
const label = helpers.getNavPlaceLabel(feature.properties.label);
// → "Current Location of the Laocoön Bronze"

data:
An ordered list of descriptions to be displayed to the user when they interact with the resource, given as pairs of human readable label and value entries.
<Metadata
  metadata={[
    {
      label: {
        none: ["Creator"],
      },
      value: {
        none: ["Fava, Antonio, 1949-"],
      },
    },
    {
      label: {
        none: ["Date"],
      },
      value: {
        none: ["2012"],
      },
    },
  ]}
/>
<dl class="c-PJLV">
  <div role="group" data-label="creator">
    <dt class="c-PJLV">Creator</dt>
    <dd class="c-PJLV">Fava, Antonio, 1949-</dd>
  </div>
  <div role="group" data-label="date">
    <dt class="c-PJLV">Date</dt>
    <dd class="c-PJLV">2012</dd>
  </div>
</dl>

data.react#React:
import { Metadata } from "@samvera/clover-iiif/primitives";
const CustomMetadata = ({ metadata }) => {
  return <Metadata metadata={metadata} />;
};
export default CustomMetadata;

data.html-attributes#HTML Attributes:
Metadata, like all Clover IIIF primitives accept common HTMLElement attributes. Use the JSX style className prop to add custom classes. The same attribute methodology can be used for id, style, title, data-*, and aria-* props.
<Metadata
  metadata={[
    {
      label: {
        none: ["Creator"],
      },
      value: {
        none: ["Fava, Antonio, 1949-"],
      },
    },
    {
      label: {
        none: ["Date"],
      },
      value: {
        none: ["2012"],
      },
    },
  ]}
  style={{ color: "red" }}
/>
<dl style="color: red;" class="c-PJLV">
  <div role="group" data-label="creator">
    <dt class="c-PJLV">Creator</dt>
    <dd class="c-PJLV">Fava, Antonio, 1949-</dd>
  </div>
  <div role="group" data-label="date">
    <dt class="c-PJLV">Date</dt>
    <dd class="c-PJLV">2012</dd>
  </div>
</dl>

data.language#Language:
Additional to being rendered to the DOM like other attributes, the value of lang will couple with InternationalString props to output the denoted label, value, summary entries. If lang is undefined, entries will default to the first entry in the array index. The value of lang should be a two letter BCP 47 language code.
<Metadata
  metadata={[
    {
      label: {
        en: ["Associated"],
        de: ["Beteiligte"],
      },
      value: {
        en: ["Jan Brueghel the Elder"],
        de: ["Jan (der Ältere) Brueghel"],
      },
    },
    {
      label: {
        en: ["Technique"],
        de: ["Technik"],
      },
      value: {
        en: ["Oil", "copper"],
        de: ["Öl", "Kupfer"],
      },
    },
  ]}
  lang="de"
/>
<dl lang="de" class="c-PJLV">
  <div role="group" data-label="associated">
    <dt lang="de" class="c-PJLV">
      Beteiligte
    </dt>
    <dd lang="de" class="c-PJLV">
      Jan (der Ältere) Brueghel
    </dd>
  </div>
  <div role="group" data-label="technique">
    <dt lang="de" class="c-PJLV">
      Technik
    </dt>
    <dd lang="de" class="c-PJLV">
      Öl, Kupfer
    </dd>
  </div>
</dl>

data.custom-values#Custom Values:
If a consuming application requires rendering specific metadata item values in a custom pattern, the customValueContent prop can be used. The pattern requires matchingLabel following https://iiif.io/api/presentation/3.0/#label and Content as a ReactElement carrying props. The element set for Content must map props.value to the appropriate code in the custom pattern.In the example below, the value of Pantaloon with a matching label of { none: ["Subject"] } would be rendered as <dd><a href="https://example.org/?subject=Pantaloon">Pantaloon</a><dd>, while the value entry of comic masks would render simply as <dd>comic masks</dd>.
const metadata = [
  {
    label: { none: ["Genre"] },
    value: { none: ["comic masks"] },
  },
  {
    label: { none: ["Subject"] },
    value: { none: ["Pantaloon"] },
  },
];
const CustomValueSubject = (props) => (
  <a href={encodeURI(`https://example.org/?subject=${props.value}`)}>
    {props.value}
  </a>
);
const customValueContent = [
  {
    matchingLabel: { none: ["Subject"] },
    Content: <CustomValueSubject />,
  },
];
return <Metadata metadata={metadata} customValueContent={customValueContent} />;

data.react-prefetched-manifest#React (prefetc:
In some use cases, applications may wish to prefetch a IIIF Manifest or Collection and pass it as a JSON object to the Viewer component. This can be done by passing the JSON object directly to the iiifContent prop.
const prefetchedManifestJson = {
  "@context": "http://iiif.io/api/presentation/3/context.json",
  id: "https://iiif.io/api/cookbook/recipe/0001-mvm-image/manifest.json",
  type: "Manifest",
  label: {
    en: ["Single Image Example"],
  },
  items: [
    {
      id: "https://iiif.io/api/cookbook/recipe/0001-mvm-image/canvas/p1",
      type: "Canvas",
      height: 1800,
      width: 1200,
      items: [
        {
          id: "https://iiif.io/api/cookbook/recipe/0001-mvm-image/page/p1/1",
          type: "AnnotationPage",
          items: [
            {
              id: "https://iiif.io/api/cookbook/recipe/0001-mvm-image/annotation/p0001-image",
              type: "Annotation",
              motivation: "painting",
              body: {
                id: "http://iiif.io/api/presentation/2.1/example/fixtures/resources/page1-full.png",
                type: "Image",
                format: "image/png",
                height: 1800,
                width: 1200,
              },
              target:
                "https://iiif.io/api/cookbook/recipe/0001-mvm-image/canvas/p1",
            },
          ],
        },
      ],
    },
  ],
};
<Viewer iiifContent={prefetchedManifestJson} />

data.nextjs#Next.js:
Implementation with Next.js requires a dynamic import utilizing next/dynamic. This is due to Next's node compilation method creating issue with an OpenSeadragon (a dependency of Clover IIIF) assumption of a browser document object.
import dynamic from "next/dynamic";
const Viewer = dynamic(
  () => import("@samvera/clover-iiif").then((Clover) => Clover.Viewer),
  {
    ssr: false,
  },
);
const MyCustomViewer = () => {
  const iiifContent =
    "https://api.dc.library.northwestern.edu/api/v2/collections/c373ecd2-2c45-45f2-9f9e-52dc244870bd?as=iiif";
  return <Viewer iiifContent={iiifContent} />;
};

data.map-display#Map Display:
The Viewer can use the Clover Map component as its primary canvas display when navPlace data is available. This is opt-in through options.map.enabled.With navPlaceLevel: "auto", Clover displays the most specific available map data for the current view: Annotation, Canvas, Manifest, then Collection. Use a fixed level to force a Collection, Manifest, Canvas, Annotation, or all available navPlace features.This example adds Manifest-level navPlace to Northwestern's Crossing the Pend d'Oreille - Kalispel Manifest. The point geometry uses the Pend Oreille River GeoNames record coordinates, and the map popup is enriched from the Manifest label, summary, and thumbnail.
const northwesternManifest = await fetch(
  "https://api.dc.library.northwestern.edu/api/v2/works/8a833741-74a8-40dc-bd1d-c416a3b1bb38?as=iiif",
).then((response) => response.json());
const manifest = {
  ...northwesternManifest,
  summary: {
    none: [
      "Photogravure from Edward S. Curtis's The North American Indian, Volume 7, mapped to the Pend Oreille River GeoNames record.",
    ],
  },
  navPlace: {
    type: "FeatureCollection",
    features: [
      {
        type: "Feature",
        id: "https://www.geonames.org/7315798/pend-oreille-river.html",
        properties: {
          label: { none: ["Pend Oreille River"] },
        },
        geometry: {
          type: "Point",
          coordinates: [-117.61775, 49.00381],
        },
      },
    ],
  },
};
<div style={{ position: "relative", height: "580px" }}>
  <Viewer
    iiifContent={manifest}
    options={{
      canvasHeight: "500px",
      showIIIFBadge: false,
      informationPanel: {
        open: false,
        renderToggle: false,
      },
      map: {
        enabled: true,
        navPlaceLevel: "Manifest",
        fitToData: true,
      },
    }}
  />
</div>;
<Viewer
  iiifContent="https://iiif.io/api/cookbook/recipe/0240-navPlace-on-canvases/manifest.json"
  options={{
    map: {
      enabled: true,
      navPlaceLevel: "auto",
      fitToData: true,
    },
  }}
/>
Prop	Type	Required	Default	options.map.enabled	boolean	No	false	options.map.fitToData	boolean	No	true	options.map.navPlaceLevel	auto | Collection | Manifest | Canvas | Annotation | all	No	auto	options.map.showImageOverlay	boolean	No	false	options.map.imageOverlayOpacity	number (0–1)	No	0.65	options.map.showControlPoints	boolean	No	true	options.map.overlayScope	manifest | canvas	No	manifest	
When showImageOverlay is enabled, Clover auto-discovers Georeference Extension annotations (motivation: "georeferencing") on the in-scope canvases and warps the source images onto the map via @allmaps/maplibre. Canvas-sourced annotations are adapted to each canvas's painting image service automatically. overlayScope: "manifest" (default) renders every georeferenced sheet in the manifest at once; "canvas" follows the active canvas. See Image Overlays for a worked example combining multiple sheets with navPlace geometry.

data.annotation-motivations#Annotation Motiva:
Limit which textual annotations render inside the Information Panel by specifying the motivations to display. When set, Clover filters each manifest annotation page and only renders annotations whose motivation matches the provided list. Leave undefined (the default) to render every motivation.
<Viewer
  iiifContent="https://example.org/iiif/manifest"
  options={{
    annotations: {
      motivations: ["commenting", "transcribing"],
    },
  }}
/>

data.automatic-height#Automatic Height:
If the height is set to auto or 100%, the Viewer will expand to the height of its wrapping container element. The wrapping element must have a position relative, along with a defined height for this to display as expected. Be aware to set a z-index value of 0 or an applicable value within your consuming application to ensure the viewer does not conflict with other page elements.
export default function App() {
  const iiifContent =
    "https://api.dc.library.northwestern.edu/api/v2/works/8a833741-74a8-40dc-bd1d-c416a3b1bb38?as=iiif";
  const options = {
    canvasHeight: "auto", // or "100%"
  };
  return (
    <div style={{ position: "relative", height: "80vh", zIndex: "0" }}>
      <Viewer iiifContent={iiifContent} options={options} />
    </div>
  );
}

data.media-search#Media Search:
Manifests with more than one canvas render a media strip below the viewer, with a
search toggle that filters the strip by canvas label. Set
options.showMediaSearch to false to hide the toggle; the strip and its
previous/next navigation are unaffected.
const options = {
  showMediaSearch: false,
};

data.information-panel#Information Panel:
The information panel is a collapsible panel that displays information about the current Manifest and renders supplementing resources for the active canvas. It is rendered by default, but can be configured to be hidden or to render only certain tabs.
Prop	Type	Required	Default	options.informationPanel.open	boolean	No	true	options.informationPanel.vtt.autoScroll	See Auto Scroll	No	true	options.informationPanel.renderAbout	boolean	No	true	options.informationPanel.renderAnnotation	boolean	No	true	options.informationPanel.renderSupplementing	boolean	No	true	options.informationPanel.renderToggle	boolean	No	true	options.informationPanel.toggleComponent	React.ComponentType	No		options.informationPanel.renderContentSearch	boolean	No	true	options.informationPanel.renderCanvasSummary	boolean	No	false	options.informationPanel.defaultTab	string	No		options.informationPanel.annotationTabLabel	string	No		
Set renderCanvasSummary to true to show the active canvas's summary above
the manifest's own, for manifests that describe each image rather than only the
object. It follows the active canvas and renders nothing when that canvas has no
summary. Off by default, since it adds text to the About tab.If renderAbout is true, Clover will use the About tab as the default tab. Use options.informationPanel.defaultTab to set the default tab.If you want content search to be the default tab, use manifest-content-search
<Viewer
  iiifContent="https://example.com/manifest/1"
  options={{
    informationPanel: {
      defaultTab: "manifest-content-search",
    },
  }}
/>
If the manifest has annotations, and you want one of the anotations to be the default tab, use the id from the annotation page.
{
  "@context": ["http://iiif.io/api/presentation/3/context.json"],
  "type": "Manifest",
   ...
  "items": [
    {
      "id": "http://example.com/manifest/canvas/1",
      "type": "Canvas",
      "height": 1000,
      "width": 2000,
      "annotations": [
        {
          "id": "http://example.com/manifest/annotation/1",
          "type": "AnnotationPage",
          "items": [...]
        }
      ]
    }
  ]
}
<Viewer
  iiifContent="https://example.com/manifest/1"
  options={{
    informationPanel: {
      defaultTab: "http://example.com/manifest/annotation/1",
    },
  }}
/>

data.content-state-callback#Content State Cal:
You can use the contentStateCallback prop to receive the current content state as a base64 encoded JSON string and as raw JSON. Using this, you can provide a consuming application the view of the user. This could helpful for sharing or storing the state for later use by a user. To review this further, see Content State.
  const handleContentStateCallback = ({ encoded, json }) => {
    console.log({
      encoded, // base64 encoded JSON
      json, // raw JSON
    });
  };
  <Viewer
    iiifContent="https://iiif.harvardartmuseums.org/manifests/object/299837"
    contentStateCallback={handleContentStateCallback}
  />;
Note: Inspect the page to track your console log.

data.iiif-content-search#IIIF Content Search:
Clover supports IIIF Content Search v2. In order to display content search in the information panel, add a content search service to the manifest.
{
  "@context": ["http://iiif.io/api/presentation/3/context.json"],
  "type": "Manifest",
  ...
  "service": [
    {
      "id": "https://example.com/search",
      "type": "SearchService2"
    }
  ]
}
Prop	Type	Required	Default	iiifContentSearchQuery.q	string	No		options.contentSearch.searchResultsLimit	number	No	20	options.contentSearch.overlays.backgroundColor	string	No	#ff66660	options.contentSearch.overlays.borderColor	string	No	#990000	options.contentSearch.overlays.borderType	string	No	solid	options.contentSearch.overlays.borderWidth	string	No	1px	options.contentSearch.overlays.opacity	string	No	0.5	options.contentSearch.overlays.renderOverlays	boolean	No	true	options.contentSearch.overlays.zoomLevel	number	No	4	
Many sites have a search functionality that returns a list objects that match the search terms. Clicking on a search result will display a details page for one object. If you want to highlight the search terms when the Clover image viewer loads on the details page, use iiifContentSearchQuery when setting up the viewer.
<Viewer
  iiifContent="https://example.com/manifest/1"
  iiifContentSearchQuery={{
    q: "my search terms",
  }}
/>
options.contentSearch.searchResultsLimit is the maximum number of search results to display per canvas in the information panel. If set to undefined, Clover will show all search results.By default, Clover's content search will draw light red boxes in the image viewer for each search result returned by the search service. You can set the appearance of the highlighted boxes using options.contentSearch.overlays. If you don't want the search results to be highlighted, set options.contentSearch.overlays.renderOverlays to false.When you click on the list of search results, Clover will pan and zoom to the location of that search result. You can set the zoom level using options.contentSearch.overlays.zoomLevel. A small zoom level will zoom in real close; a large zoom level will zoom in less.

data.basic-configuration#Basic Configuration:
Example customization of various options.
const options = {
  // Primary title (Manifest label) for top level canvas.  Defaults to true
  showTitle: false,
  // IIIF Badge and popover containing options.  Defaults to true
  showIIIFBadge: false,
  // Ignore supplementing canvases by label value that are not for captioning
  ignoreCaptionLabels: ['Chapters'],
  // Override canvas background color, defaults to #1a1d1e
  canvasBackgroundColor: "#000",
}
<Viewer
  iiifContent="https://api.dc.library.northwestern.edu/api/v2/works/8a833741-74a8-40dc-bd1d-c416a3b1bb38?as=iiif"
  options={options}
/>

data.scroll-to-zoom#Scroll to Zoom:
By default, Clover disables scrolling to zoom in the OpenSeadragon canvas. You can enable this by setting the scrollToZoom option to true in the options.openSeadragon.gestureSettingsMouse configuration. This allows users to zoom in and out of the canvas using their mouse scroll wheel or trackpad gestures.
const options = {
  // Set canvas zooming onScoll (this defaults to false)
  openSeadragon: {
    gestureSettingsMouse: {
      scrollToZoom: true;
    }
  }
}
<Viewer
  iiifContent="https://api.artic.edu/api/v1/artworks/16568/manifest.json"
  options={options}
/>

data.active-canvas#Active Canvas:
Example on using canvasIdCallback to return to your consuming application the active canvas ID. This will return as a string.
const iiifContent =
  "https://api.dc.library.northwestern.edu/api/v2/works/8a833741-74a8-40dc-bd1d-c416a3b1bb38?as=iiif";
const handlCanvasIdCallback = (activeCanvasId) => {
  if (activeCanvasId) console.log(activeCanvasId);
};
return (
  <Viewer iiifContent={iiifContent} canvasIdCallback={handlCanvasIdCallback} />
);

data.captions#Captions:
WebVTT content resources are the source for both content mapped closed captioning <track/> elements in the HTML 5 video player and to the navigator panel adjacent to it. You may ignore these resources as tracks if they are not intended for closed captioning or subtitling by string values matching the label of the content resource. This is a manual option within the viewer as there is no defined way for a manifest to prescribe motivation for these resources beyond supplementing.
export default function App() {
  const iiifContent =
    "https://raw.githubusercontent.com/samvera-labs/clover-iiif/main/public/fixtures/iiif/manifests/captions.json";
  const options = {
    ignoreCaptionLabels: ["Chapters"],
  };
  return <Viewer iiifContent={iiifContent} options={options} />;
}

data.custom-theme-prop#Custom Theme prop:
customTheme is deprecated in favor of the CSS custom properties above, and
is planned for removal in the next major version. It remains fully supported
until then — no change is required today.
You may also override the base theme by passing optional colors and fonts as a prop.
Naming conventions for colors are limited to those shown in the config example below.
Any subset may be given; tokens you leave out keep their defaults.
const iiifContent =
  "https://api.dc.library.northwestern.edu/api/v2/works/8a833741-74a8-40dc-bd1d-c416a3b1bb38?as=iiif";
const customTheme = {
  colors: {
    /**
     * Black and dark grays in a light theme.
     * All must contrast to 4.5 or greater with `secondary`.
     */
    primary: "#37474F",
    primaryMuted: "#546E7A",
    primaryAlt: "#263238",
    /**
     * Key brand color(s).
     * `accent` must contrast to 4.5 or greater with `secondary`.
     */
    accent: "#C62828",
    accentMuted: "#E57373",
    accentAlt: "#B71C1C",
    /**
     * White and light grays in a light theme.
     * All must must contrast to 4.5 or greater with `primary` and  `accent`.
     */
    secondary: "#FFFFFF",
    secondaryMuted: "#ECEFF1",
    secondaryAlt: "#CFD8DC",
  },
  fonts: {
    sans: "'Helvetica Neue', sans-serif",
    display: "Optima, Georgia, Arial, sans-serif",
  },
};
return <Viewer iiifContent={iiifContent} customTheme={customTheme} />;
customTheme is applied as --clover-* custom properties on the Viewer's root element,
so the two approaches are the same mechanism underneath. Setting a token on an ancestor
and passing customTheme therefore combine as you would expect: the prop wins inside
the Viewer, because it is declared closer to the component.

data.request-headers#Request Headers:
In some cases, a client may need to request Manifest or Collection resources with custom request headers, ex: Authorization. This can be done by passing a requestHeaders object to the options prop. This object will be passed to the request call made by the Viewer. Accepted header keys are defined in the IncomingHttpHeaders interface.
const iiifContent =
  "https://api.dc.library.northwestern.edu/api/v2/works/8a833741-74a8-40dc-bd1d-c416a3b1bb38?as=iiif";
const token = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...";
return (
  <Viewer
    iiifContent={iiifContent}
    options={{
      requestHeaders: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${token}`,
      },
    }}
  />
);

data.custom-loading-component#Custom Loading:
Clients may choose to override the default loading component that displays while the IIIF resource is fetched and loaded into state.
<Viewer
  iiifContent="https://example.com/manifest/1"
  options={{
    customLoadingComponent: () => <>My custom loading component</>,
  }}
/>

data.control-buttons#Control Buttons:
Clients may replace the buttons in the image viewer's control bar with their own components. Each key is optional, so overriding one control leaves the others as Clover's.OpenSeadragon binds its handlers by element id, so a replacement must put the id it is given on the element it wants clicks from. It should also use label as the accessible name, since Clover's own svg title is not rendered. Everything else — shape, size, markup, styling — belongs to the client.
// Spread buttonProps and the control works; the element and its styling are yours.
const ZoomIn = ({ buttonProps }) => (
  <button {...buttonProps} className="my-square-button">
    <MyZoomInIcon />
  </button>
);
<Viewer
  iiifContent="https://example.com/manifest/1"
  options={{
    controlButtons: { zoomIn: ZoomIn },
  }}
/>;
Each replacement receives buttonProps (the id OpenSeadragon binds to, type, and the accessible name), icon (Clover's own glyph, if you want to keep it), and label as plain text. Render whatever element you like, in any shape, as long as buttonProps is spread onto the interactive element.
Key	Control	zoomIn	Zoom in	zoomOut	Zoom out	fullPage	Full screen	rotateRight	Rotate right	rotateLeft	Rotate left	reset	Reset zoom and rotation	
Each control is still gated on its OpenSeadragon flag (showZoomControl, showFullPageControl, showRotationControl, showHomeControl), so a replacement for a hidden control is not rendered. Note that options.openSeadragon.navImages has no effect: Clover supplies OpenSeadragon with button elements, and OpenSeadragon skips its own control images when it is given one.Two things to know when writing a replacement:
Spread buttonProps. It carries the id OpenSeadragon binds its handlers to and the accessible name. A component that drops it renders a button that looks right and does nothing; Clover logs a warning outside production when that happens.
Define the component at module scope. A component declared inline in options is a new type on each render, which remounts the button and leaves OpenSeadragon bound to the discarded element.
OpenSeadragon sets display: inline-block and position: relative on the element as inline styles, which no class can override, so centre the glyph with margin: auto or on a wrapper inside the button rather than making the button a flex container. Clover's own spacing (margin-left: 0.618rem between controls) does not apply to a replacement, so add it if you are replacing only some of them.The information panel toggle sits outside this control bar and is replaced through options.informationPanel.toggleComponent. It is driven by Clover's state rather than OpenSeadragon, so its buttonProps carry the click handler and aria-expanded instead of an id, and none of the caveats above apply to it. isOpen is passed separately so the glyph can follow the panel state. Replacing the controls without it tends to look unfinished, since the default toggle keeps Clover's own shape.Clover positions the replacement where its own toggle sits, so it only needs to supply the button itself.
const PanelToggle = ({ buttonProps, isOpen }) => (
  <button {...buttonProps} className="my-square-button">
    {isOpen ? <MyCloseIcon /> : <MyPanelIcon />}
  </button>
);
<Viewer
  iiifContent="https://example.com/manifest/1"
  options={{
    informationPanel: { toggleComponent: PanelToggle },
  }}
/>;

data.custom-canvas-displays#Custom canvas dis:
Clients may wish to use their own display components instead of Clover Viewer's default displays (OpenSeadragon for images and HTML Video Player for audio/video). The Viewer component allows a client to target individual canvas items in a IIIF Manifest by either direct reference to a canvas id or format (ie. video/ogg). See the Type Definition below for CustomDisplay, and an example implementation.
import AnotherCustomDisplay from "./AnotherCustomDisplay";
type CustomDisplay = {
  display: {
    component: React.ElementType;
    componentProps: {
      // Any custom props you want to pass to your component
      [key: string]: any;
    };
  };
  target: {
    canvasId: string[];
    paintingFormat: string[]; // "application/pdf" or "application/epub+zip"
  };
};
function MyCustomDisplay({ id, annotationBody, ...restProps }: CustomDisplay) {
  return (
    <div>
      <h1>My Custom Display</h1>
      <p>Canvas ID: {id}</p>
      <p>Annotation Body:</p>
      <pre>{JSON.stringify(annotationBody)}</pre>
      <p>Custom props:</p>
      <pre>{JSON.stringify(restProps)}</pre>
      ...your display here
    </div>
  );
}
<Viewer
  iiifContent={iiifContent}
  customDisplays={[
    {
      display: {
        component: MyCustomDisplay,
        componentProps: {
          foo: "bar",
        },
      },
      target: {
        canvasId: [
          "https://uri-for-a-canvas-id/access/0",
          "https://uri-for-a-canvas-id/access/1",
        ],
      },
    },
    {
      display: {
        component: AnotherCustomDisplay,
      },
      target: {
        paintingFormat: ["application/pdf", "image/gif"],
      },
    },
  ]}
/>;
The Viewer component will pass the following props to your custom display component:
id: The canvas id for the resource being rendered. This may be helpful if you wanted to use the canvas id to fetch additional data from your application's API.
annotationBody: The body value for a canvas Annotation item with motivation "painting".
{
  "id": "https://uri-for-a-canvas-id/access/0",
  "type": "Annotation",
  "motivation": "painting",
  "body": {
    "format": "application/pdf",
    "height": 1686,
    "id": "http://localhost:3000/media/pdf/file-sample_150kB.pdf",
    "width": 1192
  }
}
See a complete recipe for a PDF Viewer using custom canvas displays.

data.plugins#Plugins:
Clover supports 3rd-party plugins as a way to add more functionality to Clover. To add plugins, use the plugins prop. plugins will accept an array of objects, with each object representing a plugin.People can use prebuilt plugins or create their own plugins. To install a prebuilt plugin, people should follow the instructions for the particular plugin.Here's an example of using two plugins. PluginA adds a button to imageViewer.controls. PluginB adds a tab to informationPanel.
import PluginA from "plugin-A";
import PluginB from "plugin-B";
export default function App() {
  return (
    <Viewer
      iiifContent={iiifContent}
      plugins={[
        {
          id: "Plugin A",
          imageViewer: {
            controls: {
              component: PluginA,
            },
          },
        },
        {
          id: "Plugin B",
          informationPanel: {
            component: PluginB,
            componentProps: {
              objectId: 456,
            },
            label: { none: ["My Plugin"] },
          },
        },
      ]}
    />
  );
}
Prop	Type	Required	Default	id	string	yes		imageViewer.controls	object	No		imageViewer.controls.component	React Component	yes		imageViewer.controls.componentProps	object	no		informationPanel	object	No		informationPanel.component	React Component	yes		informationPanel.componentProps	object	no		informationPanel.label	object	yes		
id - unique id for the pluginimageViewer.controls - If you want to add a custom component to image viewer controls, use imageViewer.controls.imageViewer.controls.component - The component to render.imageViewer.controls.componentProps - Props passed to the controls component.informationPanel - If you want to add a custom component to the information panel, use informationPanel.informationPanel.component - The component to render.informationPanel.componentProps - Props passed to the information panel component.informationPanel.label - The text that is displayed in the tab.

data.instructions-for-creating-a-plugin#Instr:
Clover offers these features to support plugins:
Renders custom React components in certain areas of the Clover Viewer. Areas include image viewer controls and information panel.
Gives plugins the ability to access and change the state of the Clover Viewer via props
Pass in props to the plugin components
Prop	Description	canvas	active canvas object	useViewerDispatch	React hook to update the Viewer context store	useViewerState	React hook to access the Viewer context store	
Here is an example plugin that has both imageViewer.controls and informationPanel. Plugin components have access to canvas, useViewerDispatch, and useViewerState via props.
// PluginButton.tsx
export default function PluginButton(props) {
  const { canvas, useViewerDispatch, useViewerState } = props;
  // use useViewerState to access to viewer state properties such as openSeadragonViewer, etc
  const viewerState = useViewerState();
  const { openSeadragonViewer, activeManifest } = viewerState;
  // use useViewerDispatch to update viewer state
  const dispatch = useViewerDispatch();
  function clickHandler() {
    dispatch({
      type: "updateOSDImageLoaded",
      OSDImageLoaded: false,
    });
  }
  return (
    <button
      onClick={clickHandler}
      style={{
        backgroundColor: "var(--colors-primary)",
        borderRadius: "2rem",
        width: "2rem",
        margin: "0px 0px 0px 0.618rem",
      }}
    >
      <b>P</b>
    </button>
  );
}
// PluginInfoPanel.tsx
export default function PluginInfoPanel(props) {
  const {
    canvas,
    useViewerDispatch,
    useViewerState,
    // componentProps
    objectId,
  } = props;
  return (
    <div style={{ padding: "0px 1.618rem 2rem" }}>
      <p>Plugin Info Panel</p>
      <p>objectId: {objectId}</p>
    </div>
  );
}
// App.tsx
import PluginButton from "PluginButton";
import PluginInfoPanel from "PluginInfoPanel";
export default function App() {
  return (
    <Viewer
      iiifContent="https://iiif.io/api/cookbook/recipe/0001-mvm-image/manifest.json"
      plugins={[
        {
          id: "Demo",
          imageViewer: {
            controls: {
              component: PluginButton,
            },
          },
          informationPanel: {
            component: PluginInfoPanel,
            label: { none: ["My Plugin"] },
            componentProps: {
              objectId: 456,
            },
          },
        },
      ]}
    />
  );
}
If the imageViewer.controls.component and informationPanel.component need to share state, wrap the Viewer in a context provider that is provided by the plugin.
import PluginButton from "PluginButton";
import PluginInfoPanel from "PluginInfoPanel";
import { PluginProvider } from "PluginContext";
export default function App() {
  return (
    <PluginProvider>
      <Viewer
        iiifContent="https://iiif.io/api/cookbook/recipe/0001-mvm-image/manifest.json"
        plugins={[
          {
            id: "Demo",
            imageViewer: {
              controls: {
                component: PluginButton,
              },
            },
            informationPanel: {
              component: PluginInfoPanel,
              label: { none: ["My Plugin"] },
              componentProps: {
                objectId: 456,
              },
            },
          },
        ]}
      />
    </PluginProvider>
  );
}

data.demo-usage#Demo Usage:
export const handleContentStateCallback = ({ encoded, json }) => {
  console.log({
    encoded, // base64 encoded JSON
    json, // raw JSON
  });
};
<Viewer
  contentStateCallback={handleContentStateCallback}
  options={{
    canvasHeight: "640px",
    openSeadragon: {
      gestureSettingsMouse: {
        scrollToZoom: false,
      },
    },
    showIIIFBadge: false,
  }}
